const TEST_MODE = true;
const TEST_DATE = '2026-08-31';

const date = TEST_MODE
  ? TEST_DATE
  : new Intl.DateTimeFormat('en-CA', {
      timeZone: 'Asia/Ho_Chi_Minh',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).format(new Date());

const tomorrow = new Date(
  Date.parse(date + 'T00:00:00Z') + 86400000
).toISOString().slice(0, 10);

return date.slice(0, 7) !== tomorrow.slice(0, 7)
  ? $input.all()
  : [];

